      if constexpr (Upper) {
        if (w < small_[1].value) return S{0};
      } else {
        if (w <= small_[1].value) return S{0};
      }
      U x = 0;
      for (U step = std::bit_floor(n_); step; step >>= 1) {
        const U next = x + step;
        if (next <= n_) {
          const bool advance = Upper ? small_[next].value <= w : small_[next].value < w;
          if (advance) { w -= small_[next].value; x = next; }
