        word|=(word<<4)&UINT64_C(0x8080808080808080);
        word|=(word<<8)&UINT64_C(0x8000800080008000);
        word|=(word<<16)&UINT64_C(0x8000000080000000);
        word|=(word<<32)&UINT64_C(0x8000000000000000);
