#ifndef INDEX_TYPE
#define INDEX_TYPE int
#endif
using S=INDEX_TYPE;using T=std::int64_t;using U=std::uint64_t;
struct Op{S l,r;T delta;};
int main(int argc,char**argv){const S n=static_cast<S>(std::strtoll(argv[1],nullptr,10));const int mode=std::atoi(argv[2]);const std::size_t count=262144;std::mt19937_64 rng(614425);std::vector<T>a(static_cast<std::size_t>(n));DynamicFenwickTree<S,T> base(n);for(S i=0;i<n;++i){a[i]=static_cast<T>(rng()%32);base.add(i,a[i]);}std::vector<Op>ops(count);for(std::size_t i=0;i<count;++i){S l=static_cast<S>(rng()%(static_cast<U>(n)+1)),r=static_cast<S>(rng()%(static_cast<U>(n)+1));if(l>r)std::swap(l,r);if(mode==1||mode==2)l=0;if(mode==3||mode==4){l=static_cast<S>(rng()%static_cast<U>(n));r=static_cast<S>(std::min<U>(static_cast<U>(n),static_cast<U>(l)+(mode==3?1:1+rng()%32)));}if(mode==5)r=l;const T delta=mode==6&&i%4==0?T(rng()%17):T{-1};if(delta>=0)l=static_cast<S>(rng()%static_cast<U>(n));ops[i]={l,r,delta};}
 // 標準の密な配列を独立参照とし、更新を含む期待値を計測前に求める。
 std::vector<T>ref(a.size()+1);for(std::size_t i=0;i<a.size();++i)for(std::size_t c=i+1;c<ref.size();c+=c&(~c+1))ref[c]+=a[i];auto prefix=[&](S end){T result=0;for(auto c=static_cast<std::size_t>(end);c;c&=c-1)result+=ref[c];return result;};U expected=0;for(const auto&o:ops){if(o.delta>=0){for(auto c=static_cast<std::size_t>(o.l)+1;c<ref.size();c+=c&(~c+1))ref[c]+=o.delta;}else{const T value=mode==2?prefix(o.r):prefix(o.r)-prefix(o.l);expected=expected*911+static_cast<U>(value);}}
 std::int64_t ns=0;U check=0;const int reps=3;for(int rep=0;rep<reps;++rep){auto model=base;U checksum=0;const auto start=std::chrono::steady_clock::now();for(const auto&o:ops){if(o.delta>=0)model.add(o.l,o.delta);else{const T value=mode==2?model.sum(o.r):model.sum(o.l,o.r);checksum=checksum*911+static_cast<U>(value);}}ns+=std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-start).count();if(checksum!=expected)return 3;check+=checksum;}
 std::cout<<ns/reps<<' '<<check<<'\n';}

