 public: using Base::Base;
};

} // namespace reinsirk::detail
template<typename S,typename T>
class DynamicFenwickTree : public reinsirk::detail::FenwickBase<S,T> {
 using Base=reinsirk::detail::FenwickBase<S,T>;
 public: using Base::Base;
};
#endif

