  struct Wide {
    std::unique_ptr<Legacy> ptr;
    Wide()=default;
    Wide(const Wide& other):ptr(other.ptr ? std::make_unique<Legacy>(*other.ptr):nullptr){}
    Wide(Wide&&)=default;
