      return;
    }
    if constexpr(DirectReads) {
      if(root_!=absent && append_add(col,delta))return;
      // 占有済みセルの祖先もすべて占有済み。
      if(dense_used(col)) {
        for(U c=col;c<=dense_width_;c+=lowbit(c))dense_values_[c]=plus(dense_values_[c],delta);
