  std::size_t size() const noexcept {
    if constexpr(DirectReads)if(root_!=absent && !dense_values_.empty()) {
      std::size_t count=root_;for(U x=root_+lowbit(root_);x<=dense_width_;x+=lowbit(x))++count;
      return count;
    }
