#define OPERATION 0
#endif
int main(int argc,char**argv){const int n=argc>1?std::atoi(argv[1]):32768;DynamicFenwickTree<int,std::int64_t> a(n);for(int i=0;i<n;++i)a.add(i,i%7);std::uint64_t check=0;
for(int i=0;i<n;++i){if constexpr(OPERATION==0)check+=a.sum(i);else if constexpr(OPERATION==1)check+=a.get(i);else if constexpr(OPERATION==2){a.set(i,i%11);check+=a.get(i);}else if constexpr(OPERATION==3){a.add(i,i%3);check+=a.get(i);}else if constexpr(OPERATION==4){check+=a.lower_bound(i)+a.upper_bound(i);}else {auto copy=a;copy.clear();copy.reset(n);check+=copy.size()+copy.stored_nodes();break;}}
