      result=plus(result,static_cast<V>(dense_values_[c]&mask));
    }
    for(U c=ml;c!=common;c-=lowbit(c)) {
      const V mask=static_cast<V>(A{0}-static_cast<A>(dense_used(c)));
      result=minus(result,static_cast<V>(dense_values_[c]&mask));
