      if(node.leaf)for(unsigned i=0;i<32;++i)p+=static_cast<unsigned>(node.keys[i]<=endpoint);
      else for(unsigned i=0;i<16;++i)p+=static_cast<unsigned>(node.keys[i]<=endpoint);
      if (p) result=plus(result,node.prefix[p-1]);
