    else if(auto* wide=std::get_if<2>(&storage_))if(wide->ptr)wide->ptr->reset(static_cast<S>(n_));
  }
  void add(S k,const T& value) {
    check_position(k);const U i=static_cast<U>(k);
    if(auto* tiny=std::get_if<1>(&storage_)) {
