      else row->template add_direct<true>(static_cast<std::uint32_t>(i)+1,value,static_cast<std::uint32_t>(n_));
      if(n_<8192 && !dense_failed_ && row->size()>=(static_cast<std::size_t>(n_)+7)/8) {
