 def close(pos):
  i=t.index('{',pos);depth=1;i+=1
  while depth:
   if t[i]=='{':depth+=1
   elif t[i]=='}':depth-=1
   i+=1
  return i
 tend=close(tiny);rend=close(row);assert t[tend:row].strip()==''
 return t[:tiny]+t[row:rend]+t[tend:row]+t[tiny:tend]+t[rend:]
for name,methods in [('rangefirst',['inline T sum(S l,S r)const']),('readsfirst',['inline T sum(S l,S r)const','inline T sum(S k)const'])]:
