// SPDX-License-Identifier: CC0-1.0
#ifndef SIRKIT_FENWICK_TEST_SOURCE
#define SIRKIT_FENWICK_TEST_SOURCE "../../../DataStructure/dynamic-binary-indexed-tree.cpp"
#endif
#include SIRKIT_FENWICK_TEST_SOURCE
#include <cassert>
#include <algorithm>
#include <cstdint>
#include <iostream>
#include <random>
#include <type_traits>
#include <vector>
std::uint64_t checks=0;
template<class T>void test(int n){using V=std::make_unsigned_t<T>;using A=decltype(V{}+0u);DynamicFenwickTree<int,T> b(n);std::vector<V>a(n),prefix(n+1);for(int i=0;i<n;++i){const T value=i==0?T{3}:i==64?static_cast<T>(-1):i==127?T{1}:T{};a[i]=static_cast<V>(value);b.add(i,value);}auto verify=[&]{prefix[0]=0;for(int i=0;i<n;++i)prefix[i+1]=static_cast<V>(static_cast<A>(prefix[i])+static_cast<A>(a[i]));const auto stored=b.stored_nodes();const int positions[]={0,64,128,192,1024,8192,16384,32768,(n/64)*64};for(int block:positions){if(block>n)continue;const int end=std::min(n,block+63);for(int l=block;l<=end;++l)for(int r=l;r<=end;++r){const auto wanted=static_cast<T>(static_cast<V>(static_cast<A>(prefix[r])-static_cast<A>(prefix[l])));assert(b.sum(l,r)==wanted);++checks;}if(block>0&&block<n){const auto expected=static_cast<T>(static_cast<V>(static_cast<A>(prefix[block+1])-static_cast<A>(prefix[block-1])));assert(b.sum(block-1,block+1)==expected);++checks;}}assert(b.stored_nodes()==stored);};verify();
 for(int k:{1,63,64,65,127,128,129,n-1})if(k>=0&&k<n){b.add(k,T{1});a[k]=static_cast<V>(static_cast<A>(a[k])+A{1});}verify();const auto total=b.sum_all();auto copy=b;assert(copy.sum_all()==total&&copy.sum(64,65)==b.sum(64,65));verify();b.clear();assert(copy.sum_all()==total);std::fill(a.begin(),a.end(),V{});verify();for(int i=0;i<n;++i)b.add(i,T{});b.add(0,T{1});a[0]=1;verify();(void)copy;}
int main(){
#ifdef SIRKIT_FENWICK_WINDOW_REDUCED
const int ns[]={8192,8193,32769};
#else
const int ns[]={8191,8192,8193,32768,32769,500000,500001};
#endif
for(int n:ns){test<std::int8_t>(n);test<std::uint8_t>(n);test<std::int16_t>(n);test<std::uint16_t>(n);test<std::int32_t>(n);test<std::uint32_t>(n);test<std::int64_t>(n);test<std::uint64_t>(n);}std::cout<<"PASS window reference checks="<<checks<<'\n';}
